#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""bg_w1_57 ~ bg_w1_67 JSON 파일 생성"""

import json, os

BASE = r"C:\Users\RENEWCOM PC\Documents\국어농장v2홈페이지\frontend\public\farm\background\wittgenstein1"

def mk(num, title, desc, subArea, tags, passages):
    obj = {
        "contentType": "BACKGROUND_KNOWLEDGE",
        "title": title,
        "description": desc,
        "targetLevel": "WITTGENSTEIN_1",
        "area": "BACKGROUND",
        "subArea": subArea,
        "competencies": ["BACKGROUND"],
        "tags": tags,
        "seedReward": {"seedType": "CORN", "count": 3, "multiplier": 1},
        "timeLimitSec": 420,
        "payload": {"passages": passages}
    }
    path = os.path.join(BASE, f"bg_w1_{num:02d}.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    print(f"  Created bg_w1_{num:02d}.json")

def q(qid, stem, choices, ans):
    return {
        "id": qid, "type": "MULTI_CHOICE", "stem": stem,
        "choices": [{"id": c[0], "text": c[1]} for c in choices],
        "answerId": ans, "scoring": {"correctDeltaSec": 10, "wrongDeltaSec": -10}
    }

